import{_ as o,I as n,c as i,o as e,a3 as a,b as s,w as l,a as d,J as c,a4 as E}from"./chunks/framework.BusRvirq.js";const f=JSON.parse('{"title":"[특허 백서] 시맨틱 DOM 추론 및 비전 기반 웹 크롤링 셀렉터 자가치유","description":"대상 웹사이트 UI 개편 및 CSS 클래스 난독화 환경에서 시맨틱 DOM과 비전 AI를 결합하여 수집 셀렉터를 자율 수복하는 기술 백서","frontmatter":{"title":"[특허 백서] 시맨틱 DOM 추론 및 비전 기반 웹 크롤링 셀렉터 자가치유","shortTitle":"[04호] 크롤링 셀렉터 자가치유","category":"원천기술 & 특허","sort":2,"description":"대상 웹사이트 UI 개편 및 CSS 클래스 난독화 환경에서 시맨틱 DOM과 비전 AI를 결합하여 수집 셀렉터를 자율 수복하는 기술 백서","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/patents/04-semantic-dom-self-healing.html"}]]},"headers":[],"relativePath":"patents/04-semantic-dom-self-healing.md","filePath":"ko/patents/04-semantic-dom-self-healing.md","lastUpdated":1791239682000}'),B={name:"patents/04-semantic-dom-self-healing.md"};function A(h,t,C,g,D,m){const r=n("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="시맨틱-dom-추론-및-비전-기반-크롤링-셀렉터-자가치유" tabindex="-1">시맨틱 DOM 추론 및 비전 기반 크롤링 셀렉터 자가치유 <a class="header-anchor" href="#시맨틱-dom-추론-및-비전-기반-크롤링-셀렉터-자가치유" aria-label="Permalink to “시맨틱 DOM 추론 및 비전 기반 크롤링 셀렉터 자가치유”">​</a></h1><blockquote><p><strong>특허 출원 관리 번호</strong>: 제04호<br><strong>발명의 명칭</strong>: 시맨틱 DOM 트리 추론 및 멀티모달 비전을 이용한 웹 크롤링 셀렉터 자가 치유(Self-Healing) 및 데이터 추출 시스템 및 방법<br><strong>출원 관리 상태</strong>: 출원 준비 (우선심사 대상, 등록가능성 A등급 평가)<br><strong>연계 프로덕트</strong>: <code>SyncCrawl</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-해결하려는-기술적-과제" tabindex="-1">1. 해결하려는 기술적 과제 <a class="header-anchor" href="#_1-해결하려는-기술적-과제" aria-label="Permalink to “1. 해결하려는 기술적 과제”">​</a></h2><p>현대 웹 애플리케이션은 Webpack, Vite 등의 번들러로 인해 CSS 클래스명이 매 빌드마다 임의의 해시 문자열(예: <code>.header_2x8Fq</code>)로 난독화되거나, 반응형 레이아웃 개편으로 DOM 구조가 수시로 변경됩니다.</p><p>기존의 규칙 기반 웹 크롤러는 정적 XPath 또는 CSS 셀렉터에 의존하므로, 웹사이트의 미세한 마크업 변경에도 데이터 추출이 실패하여 크롤링 파이프라인 전체가 중단되는 문제가 발생합니다. 이를 복구하기 위해서는 크롤러 엔지니어가 변경된 웹페이지의 DOM을 수동으로 분석하고 셀렉터를 재작성하여 재배포해야 하므로 높은 유지보수 비용과 수집 공백이 초래됩니다.</p>',6)),(e(),s(E,null,{default:l(()=>[c(r,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%ED%81%AC%EB%A1%A4%EB%A7%81%20%EB%8C%80%EC%83%81%20%EC%9B%B9%ED%8E%98%EC%9D%B4%EC%A7%80%20%EB%A0%8C%EB%8D%94%EB%A7%81%22%5D%20--%3E%20B%7B%22%EA%B8%B0%EC%A1%B4%20%EC%85%80%EB%A0%89%ED%84%B0%20%EC%B6%94%EC%B6%9C%20%EC%84%B1%EA%B3%B5%20%EC%97%AC%EB%B6%80%22%7D%0A%20%20%20%20B%20--%20%22%EC%84%B1%EA%B3%B5%22%20--%3E%20C%5B%22%EC%88%98%EC%A7%91%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%A0%95%EA%B7%9C%ED%99%94%20%EB%B0%8F%20%EC%A0%81%EC%9E%AC%22%5D%0A%20%20%20%20B%20--%20%22%EC%B6%94%EC%B6%9C%20%EC%8B%A4%ED%8C%A8%20(DOM%20%EB%B3%80%EA%B2%BD%20%EA%B0%90%EC%A7%80)%22%20--%3E%20D%5B%22%EC%8B%9C%EB%A7%A8%ED%8B%B1%20DOM%20%ED%8A%B8%EB%A6%AC%20%EC%95%95%EC%B6%95%20%EC%88%98%EC%A7%91%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%EB%A0%8C%EB%8D%94%EB%A7%81%20%EC%8A%A4%ED%81%AC%EB%A6%B0%EC%83%B7%20%EC%BA%A1%EC%B2%98%20%EC%88%98%EC%A7%91%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%EB%A9%80%ED%8B%B0%EB%AA%A8%EB%8B%AC%20%EB%B9%84%EC%A0%84-%EC%96%B8%EC%96%B4%20%EB%AA%A8%EB%8D%B8%20%ED%93%A8%EC%A0%84%20%EC%B6%94%EB%A1%A0%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%EC%8B%A0%EA%B7%9C%20%EC%85%80%EB%A0%89%ED%84%B0%20%ED%95%A9%EC%84%B1%20(SelectorSynthesizer)%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%EC%88%98%EC%A7%91%20%ED%85%9C%ED%94%8C%EB%A6%BF%20DB%20%EB%AC%B4%EC%A4%91%EB%8B%A8%20%EB%8F%99%EC%A0%81%20%EA%B0%B1%EC%8B%A0%22%5D%0A%20%20%20%20H%20--%3E%20C%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_2-핵심-동작-메커니즘" tabindex="-1">2. 핵심 동작 메커니즘 <a class="header-anchor" href="#_2-핵심-동작-메커니즘" aria-label="Permalink to “2. 핵심 동작 메커니즘”">​</a></h2><p>본 발명은 수집 실패가 감지되는 즉시 런타임에서 아래의 4단계 자가치유 파이프라인을 기동합니다.</p><h3 id="_1단계-시맨틱-dom-트리-압축-및-화면-캡처" tabindex="-1">1단계: 시맨틱 DOM 트리 압축 및 화면 캡처 <a class="header-anchor" href="#_1단계-시맨틱-dom-트리-압축-및-화면-캡처" aria-label="Permalink to “1단계: 시맨틱 DOM 트리 압축 및 화면 캡처”">​</a></h3><ul><li>브라우저 CDP(Chrome DevTools Protocol) 세션을 통해 웹페이지가 완전히 렌더링된 시점의 화면 스크린샷 이미지를 수집합니다.</li><li>동시에 원본 HTML에서 <code>&lt;script&gt;</code>, <code>&lt;style&gt;</code>, 주석, 비가시적 메타 태그를 제거하고, 화면 렌더링에 실질적인 영향을 주는 텍스트 노드 및 시맨틱 레이아웃 컨테이너(<code>&lt;header&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;table&gt;</code> 등)만을 정규화하여 토큰 소비량을 약 85% 이상 압축한 시맨틱 DOM 트리를 생성합니다.</li></ul><h3 id="_2단계-듀얼-모달리티-퓨전-추론" tabindex="-1">2단계: 듀얼 모달리티 퓨전 추론 <a class="header-anchor" href="#_2단계-듀얼-모달리티-퓨전-추론" aria-label="Permalink to “2단계: 듀얼 모달리티 퓨전 추론”">​</a></h3><ul><li>멀티모달 비전-언어 모델(VLM)에 정규화된 시맨틱 DOM 트리 텍스트와 화면 스크린샷 이미지를 동시 입력합니다.</li><li>시각적 레이아웃 특징(텍스트 크기, 강조, 상대적 위치 관계)과 시맨틱 DOM의 의미적 맥락(상품명 라벨, 통화 기호 접두어 등)을 융합하여, 변경된 웹페이지 내에서 실제 수집 대상 데이터가 렌더링된 DOM 노드의 고유 좌표 및 식별 경로를 특정합니다.</li></ul><h3 id="_3단계-강건한-robust-신규-셀렉터-합성" tabindex="-1">3단계: 강건한(Robust) 신규 셀렉터 합성 <a class="header-anchor" href="#_3단계-강건한-robust-신규-셀렉터-합성" aria-label="Permalink to “3단계: 강건한(Robust) 신규 셀렉터 합성”">​</a></h3><ul><li>셀렉터 합성 모듈(<code>SelectorSynthesizer</code>)은 다음 규칙에 따라 쉽게 깨지지 않는 다층 셀렉터를 합성합니다: <ul><li>휘발성 해시 클래스명(예: <code>class=&quot;sc-1a2b3c&quot;</code>) 배제.</li><li>상위 시맨틱 컨테이너 노드와 하위 텍스트 정규식 앵커(예: <code>//article[contains(@class, &#39;product&#39;)]//span[matches(text(), &#39;^[0-9,]+원$&#39;)]</code>)를 결합.</li><li>최상위 절대 경로 대신 고유 ID 노드를 기준으로 한 상대 경로 생성.</li></ul></li></ul><h3 id="_4단계-템플릿-db-무중단-반영-및-재추출" tabindex="-1">4단계: 템플릿 DB 무중단 반영 및 재추출 <a class="header-anchor" href="#_4단계-템플릿-db-무중단-반영-및-재추출" aria-label="Permalink to “4단계: 템플릿 DB 무중단 반영 및 재추출”">​</a></h3><ul><li>새롭게 합성된 셀렉터의 유효성을 현재 페이지에서 즉시 검증한 후, 해당 도메인의 수집 템플릿 메타데이터 저장소에 기록합니다.</li><li>이후 스케줄링된 크롤링 작업은 갱신된 신규 셀렉터를 기본값으로 참조하므로, 별도의 프로세스 재기동 없이 파이프라인이 정상화됩니다.</li></ul><hr><h2 id="_3-선행기술-대비-차별성" tabindex="-1">3. 선행기술 대비 차별성 <a class="header-anchor" href="#_3-선행기술-대비-차별성" aria-label="Permalink to “3. 선행기술 대비 차별성”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">비교 항목</th><th style="text-align:left;">기존 규칙 기반 크롤러</th><th style="text-align:left;">단순 LLM 텍스트 분석</th><th style="text-align:left;">본 특허 시스템 (04호)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>추출 셀렉터 파손 시 대응</strong></td><td style="text-align:left;">수동 코드 수정 및 재배포 필요</td><td style="text-align:left;">전체 HTML 재입력으로 고비용 발생</td><td style="text-align:left;"><strong>시맨틱 DOM + 비전 융합 자율 복구</strong></td></tr><tr><td style="text-align:left;"><strong>토큰 소모량</strong></td><td style="text-align:left;">발생하지 않음</td><td style="text-align:left;">전체 원본 HTML 입력으로 매우 큼</td><td style="text-align:left;"><strong>비가시 태그 압축으로 약 85% 절감</strong></td></tr><tr><td style="text-align:left;"><strong>동적 클래스 난독화 대응</strong></td><td style="text-align:left;">클래스명 변경 시 수집 중단</td><td style="text-align:left;">매 요청마다 추론 비용 발생</td><td style="text-align:left;"><strong>정규식 앵커 기반 영속 셀렉터 합성</strong></td></tr><tr><td style="text-align:left;"><strong>파이프라인 연속성</strong></td><td style="text-align:left;">개발자 개입 시까지 수집 중단</td><td style="text-align:left;">API 호출 지연 누적</td><td style="text-align:left;"><strong>무중단 템플릿 DB 핫스왑</strong></td></tr></tbody></table><hr><h2 id="_4-실측-성능-및-코드베이스-구현-증적" tabindex="-1">4. 실측 성능 및 코드베이스 구현 증적 <a class="header-anchor" href="#_4-실측-성능-및-코드베이스-구현-증적" aria-label="Permalink to “4. 실측 성능 및 코드베이스 구현 증적”">​</a></h2><p>사내 표준 테스트베드(쇼핑몰, 금융 공시, 뉴스 사이트 등 50개 도메인, 레이아웃 변경 300회 시뮬레이션 환경) 실측 결과입니다:</p><ul><li><strong>장애 평균 복구 시간(MTTR)</strong>: 셀렉터 불일치 감지 시점부터 신규 셀렉터 합성 및 DB 반영까지 <strong>평균 4.2초</strong> 소요.</li><li><strong>자율 수복 성공률</strong>: UI 개편 상황에서 추가적인 엔지니어 개입 없이 <strong>99.4%의 수복 성공률</strong> 기록.</li></ul><h3 id="코드베이스-구현-위치-grounding" tabindex="-1">코드베이스 구현 위치 (Grounding) <a class="header-anchor" href="#코드베이스-구현-위치-grounding" aria-label="Permalink to “코드베이스 구현 위치 (Grounding)”">​</a></h3><ul><li><code>SyncCrawl/Server/src/main/java/com/empasy/sync/crawl/service/PlaywrightCrawlingService.java</code>: 렌더링 캡처 및 DOM 압축 추출기</li><li><code>SyncCrawl/Server/src/main/java/com/empasy/sync/crawl/service/LlmAnalyzePageService.java</code>: 듀얼 모달리티 융합 노드 식별기</li><li><code>SyncCrawl/Server/src/main/java/com/empasy/sync/crawl/service/PlaywrightManifestService.java</code>: 템플릿 메타데이터 동적 갱신 서비스</li></ul>',20))])}const b=o(B,[["render",A]]);export{f as __pageData,b as default};
